changeSet.sql:
DO $$ BEGIN IF EXISTS (SELECT 1 FROM
			pg_constraint WHERE conname = 'fk_service_request_provider' AND
			conrelid = 't_service_request'::regclass) THEN ALTER TABLE
			public.t_service_request DROP CONSTRAINT
			fk_service_request_provider;
			END IF; END $$;

DELETE FROM public.t_service_provider
			sp WHERE
			NOT EXISTS (
			SELECT 1 FROM public.t_user u WHERE
			u.c_id = sp.c_user_id
			);

DELETE FROM public.t_service_request
			sr WHERE
			NOT EXISTS (
			SELECT 1 FROM public.t_user u WHERE
			u.c_id = sr.c_user_id
			);
